# name: balance_preference_similar_switches
# description: Among pairs whose switch counts differ by at most 1 and whose head-count imbalances |#H - n/2| differ, the proportion of choices for the more balanced sequence; observed above null_mean means people weight H/T balance more than the model's biased-coin alternative implies, below means less.
def test_statistic(df):
    a = df["sequence_a"]; b = df["sequence_b"]
    n = a.str.len().to_numpy()
    ia = np.abs(a.str.count("H").to_numpy() - n / 2)
    ib = np.abs(b.str.count("H").to_numpy() - n / 2)
    def sw(s):
        return sum(1 for x, y in zip(s, s[1:]) if x != y)
    u = pd.unique(pd.concat([a, b]))
    m = {s: sw(s) for s in u}
    swa = a.map(m).to_numpy(); swb = b.map(m).to_numpy()
    sel = (np.abs(swa - swb) <= 1) & (ia != ib)
    if sel.sum() == 0:
        return 0.5
    cl = df["chose_left"].to_numpy()[sel]
    c = np.where(ia[sel] < ib[sel], cl, 1 - cl)
    return float(np.mean(c))

# name: perfect_alternation_choice_rate
# description: Proportion of choices for a perfectly alternating sequence (HTHT.../THTH..., length>=4) when paired with a non-alternating one; observed above null_mean means the model over-penalises perfect alternation (people find it more random than predicted), below means it under-penalises it.
def test_statistic(df):
    def alt(s):
        return len(s) >= 4 and all(s[i] != s[i + 1] for i in range(len(s) - 1))
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: alt(s) for s in u}
    pa = df["sequence_a"].map(m).astype(bool)
    pb = df["sequence_b"].map(m).astype(bool)
    sel = pa ^ pb
    if sel.sum() == 0:
        return 0.5
    c = np.where(pa[sel], df["chose_left"][sel], 1 - df["chose_left"][sel])
    return float(np.mean(c))

# name: periodic_motif_choice_rate
# description: Among pairs (length>=6) where exactly one sequence is periodic with period 3 or 4 (e.g. HTHHTHHT, HHTTHHTT) and not perfectly alternating, the proportion of choices for the periodic sequence; observed below null_mean means people penalise repeating motifs more than the model (which sees only switch count and balance) predicts, above means less.
def test_statistic(df):
    def periodic(s):
        n = len(s)
        if n < 6 or all(s[i] != s[i + 1] for i in range(n - 1)):
            return False
        return any(all(s[i] == s[i + p] for i in range(n - p)) for p in (3, 4))
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: periodic(s) for s in u}
    pa = df["sequence_a"].map(m).astype(bool)
    pb = df["sequence_b"].map(m).astype(bool)
    sel = pa ^ pb
    if sel.sum() == 0:
        return 0.5
    chose_periodic = np.where(pa[sel], df["chose_left"][sel], 1 - df["chose_left"][sel])
    return float(np.mean(chose_periodic))

# name: symmetric_sequence_choice_rate
# description: Among pairs (length>=5) where exactly one sequence is mirror-symmetric (a palindrome, or the reverse of its H/T complement, e.g. HTTHHTTH, HHHHTTTT) and neither constant nor perfectly alternating, the proportion of choices for the symmetric sequence; observed below null_mean means people penalise symmetry more than the model predicts, above means the model over-penalises it.
def test_statistic(df):
    def sym(s):
        if len(s) < 5 or len(set(s)) == 1 or all(x != y for x, y in zip(s, s[1:])):
            return False
        comp = s.translate(str.maketrans("HT", "TH"))
        return s == s[::-1] or comp == s[::-1]
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: sym(s) for s in u}
    pa = df["sequence_a"].map(m).astype(bool)
    pb = df["sequence_b"].map(m).astype(bool)
    sel = pa ^ pb
    if sel.sum() == 0:
        return 0.5
    c = np.where(pa[sel], df["chose_left"][sel], 1 - df["chose_left"][sel])
    return float(np.mean(c))

# name: high_alternation_more_switches_rate
# description: Among pairs where both sequences switch on at least half their transitions and switch counts differ, the proportion of choices for the sequence with MORE switches; observed below null_mean means people stop rewarding extra alternation (or penalise it) in the high-switch regime more than the model's monotone over-alternation term predicts, above means they reward it more.
def test_statistic(df):
    a = df["sequence_a"]; b = df["sequence_b"]
    def sw(s):
        return sum(1 for x, y in zip(s, s[1:]) if x != y)
    u = pd.unique(pd.concat([a, b]))
    m = {s: sw(s) for s in u}
    swa = a.map(m).to_numpy(); swb = b.map(m).to_numpy()
    t = a.str.len().to_numpy() - 1
    sel = (swa >= t / 2) & (swb >= t / 2) & (swa != swb)
    if sel.sum() == 0:
        return 0.5
    cl = df["chose_left"].to_numpy()[sel]
    c = np.where(swa[sel] > swb[sel], cl, 1 - cl)
    return float(np.mean(c))

# name: overall_left_choice_rate
# description: Overall proportion of Left choices across all trials; observed away from null_mean means people have a side bias the model (which has no left/right term) cannot produce — above means a Left bias, below a Right bias.
def test_statistic(df):
    return float(df["chose_left"].mean())
